import { createHmac, randomBytes, timingSafeEqual } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";

/**
 * Expansion owner identity (server-only).
 *
 * There is no shared RestaurantOS account system yet (Tactical only has a
 * password-unlock cookie for its AI routes). Until a shared identity is agreed,
 * Expansion issues its own HMAC-signed, HttpOnly owner cookie. The owner id is
 * generated by the server; a client can never choose it, and a run id, brief
 * id or restaurant id in a request is never authorization on its own.
 *
 * - EXPANSION_SESSION_SECRET (>= 32 chars) signs cookies. Required in
 *   production. In development a random secret is generated once into the
 *   git-ignored data directory so local sessions survive restarts.
 * - EXPANSION_ACCESS_CODE (optional): when set, a new owner session is only
 *   issued through POST /api/expansion/session with that code. When unset,
 *   an anonymous device-bound owner is issued on first use.
 */

if (typeof window !== "undefined") throw new Error("backend/owner.ts is server-only.");

export const OWNER_COOKIE = "expansion_owner";
const COOKIE_VERSION = "v1";
const MAX_AGE_S = 60 * 60 * 24 * 180;
const OWNER_ID = /^[a-zA-Z0-9_-]{1,64}$/;

export class OwnerError extends Error {
  code: "unauthenticated" | "auth_not_configured" | "access_code_required" | "forbidden";
  constructor(code: OwnerError["code"], message: string) {
    super(message);
    this.name = "OwnerError";
    this.code = code;
  }
}

let cachedDevSecret: string | null = null;
function devSecretFile() {
  return resolve(process.cwd(), process.env.EXPANSION_DEV_SECRET_FILE ?? "src/features/expansion/data/data/.expansion-session-secret");
}

export function sessionSecret(): string {
  const configured = process.env.EXPANSION_SESSION_SECRET ?? "";
  if (configured.length >= 32) return configured;
  if (configured.length > 0) throw new OwnerError("auth_not_configured", "EXPANSION_SESSION_SECRET must be at least 32 characters.");
  if (process.env.NODE_ENV === "production") {
    throw new OwnerError("auth_not_configured", "Owner sessions are not configured: set EXPANSION_SESSION_SECRET (32+ characters) on the server.");
  }
  if (cachedDevSecret) return cachedDevSecret;
  const file = devSecretFile();
  try {
    if (existsSync(file)) {
      const stored = readFileSync(file, "utf8").trim();
      if (stored.length >= 32) return (cachedDevSecret = stored);
    }
    mkdirSync(dirname(file), { recursive: true });
    const generated = randomBytes(32).toString("hex");
    writeFileSync(file, generated, { mode: 0o600 });
    return (cachedDevSecret = generated);
  } catch {
    throw new OwnerError("auth_not_configured", "No EXPANSION_SESSION_SECRET is set and the development secret file could not be created.");
  }
}

export function accessCodeRequired(): boolean {
  return (process.env.EXPANSION_ACCESS_CODE ?? "").length > 0;
}

const sign = (payload: string) => createHmac("sha256", sessionSecret()).update(payload).digest("base64url");
const equal = (left: string, right: string) => {
  const a = Buffer.from(left);
  const b = Buffer.from(right);
  return a.length === b.length && timingSafeEqual(a, b);
};

export function newOwnerId(): string {
  return `o_${randomBytes(16).toString("base64url")}`;
}

/** Signed cookie value for an owner id (also used by tests). */
export function ownerCookieValue(ownerId: string, now = Date.now()): string {
  if (!OWNER_ID.test(ownerId)) throw new OwnerError("unauthenticated", "Invalid owner id.");
  const expires = Math.floor(now / 1000) + MAX_AGE_S;
  const payload = `${COOKIE_VERSION}.${ownerId}.${expires}`;
  return `${payload}.${sign(payload)}`;
}

export function verifyOwnerCookie(value: string | null | undefined, now = Date.now()): string | null {
  if (!value) return null;
  const parts = value.split(".");
  if (parts.length !== 4) return null;
  const [version, ownerId, expires, signature] = parts;
  if (version !== COOKIE_VERSION || !OWNER_ID.test(ownerId) || !/^\d{1,12}$/.test(expires)) return null;
  if (Number(expires) * 1000 < now) return null;
  return equal(signature, sign(`${version}.${ownerId}.${expires}`)) ? ownerId : null;
}

export function readCookie(request: Request, name: string): string | null {
  const header = request.headers.get("cookie");
  if (!header) return null;
  for (const part of header.split(";")) {
    const [key, ...rest] = part.trim().split("=");
    if (key === name) return decodeURIComponent(rest.join("="));
  }
  return null;
}

export function setOwnerCookieHeader(request: Request, ownerId: string): string {
  const secure = new URL(request.url).protocol === "https:" || request.headers.get("x-forwarded-proto") === "https";
  return `${OWNER_COOKIE}=${encodeURIComponent(ownerCookieValue(ownerId))}; Path=/api/expansion; HttpOnly; SameSite=Lax; Max-Age=${MAX_AGE_S}${secure ? "; Secure" : ""}`;
}

export function clearOwnerCookieHeader(): string {
  return `${OWNER_COOKIE}=; Path=/api/expansion; HttpOnly; SameSite=Lax; Max-Age=0`;
}

export type OwnerContext = { ownerId: string; issued: boolean; setCookie: string | null };

/**
 * Resolve the request's owner. A valid signed cookie wins. Without one, a new
 * anonymous owner is issued unless an access code is required (then 401).
 * Pass `issue: false` for routes that must never mint identities.
 */
export function resolveOwner(request: Request, options: { issue?: boolean } = {}): OwnerContext {
  const existing = verifyOwnerCookie(readCookie(request, OWNER_COOKIE));
  if (existing) return { ownerId: existing, issued: false, setCookie: null };
  if (options.issue === false) throw new OwnerError("unauthenticated", "Sign in to your Expansion workspace first.");
  if (accessCodeRequired()) {
    throw new OwnerError("access_code_required", "This workspace requires an access code. Enter it to start a private session.");
  }
  const ownerId = newOwnerId();
  return { ownerId, issued: true, setCookie: setOwnerCookieHeader(request, ownerId) };
}

export function checkAccessCode(code: unknown): boolean {
  const expected = process.env.EXPANSION_ACCESS_CODE ?? "";
  return typeof code === "string" && expected.length > 0 && equal(code, expected);
}

export function ownerFailure(error: OwnerError): Response {
  const status = error.code === "auth_not_configured" ? 503 : error.code === "forbidden" ? 403 : 401;
  return Response.json({ error: { code: error.code, message: error.message } }, { status, headers: { "Cache-Control": "private, no-store" } });
}

/** Attach a newly issued owner cookie to a route response. */
export function withOwnerCookie(response: Response, owner: OwnerContext): Response {
  if (owner.setCookie) response.headers.append("Set-Cookie", owner.setCookie);
  return response;
}
